import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DGJy295j.js";var i=JSON.parse(`{"title":"Class: BiomeManager","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: BiomeManager"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/BiomeManager"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/BiomeManager"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/worldgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/worldgen/classes/BiomeManager.md","filePath":"api/@jsprismarine/worldgen/classes/BiomeManager.md","lastUpdated":1794206055000}`),a={name:`api/@jsprismarine/worldgen/classes/BiomeManager.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/worldgen</a> / BiomeManager</p><h1 id="class-biomemanager" tabindex="-1">Class: BiomeManager <a class="header-anchor" href="#class-biomemanager" aria-label="Permalink to “Class: BiomeManager”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/85a899ab0449aff681fea72169c1083e4f9748f7/packages/worldgen/src/biome/BiomeManager.ts#L93" target="_blank" rel="noreferrer">biome/BiomeManager.ts:93</a></p><p>The per-block biome getter the surface pass reads.</p><p>A biome source answers per 4 by 4 by 4 cell. Java does not snap a block to its own cell; it picks whichever of the eight surrounding cell corners is nearest after a seeded jitter, so a biome edge wanders by a block or two instead of following the cell grid. The surface pass needs that, because a biome-conditioned rule resolved per chunk instead of per column puts the wrong block on every column the chunk&#39;s other biomes own.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new BiomeManager</strong>(<code>resolver</code>, <code>zoomSeed</code>): <code>BiomeManager</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/85a899ab0449aff681fea72169c1083e4f9748f7/packages/worldgen/src/biome/BiomeManager.ts#L111" target="_blank" rel="noreferrer">biome/BiomeManager.ts:111</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="resolver" tabindex="-1">resolver <a class="header-anchor" href="#resolver" aria-label="Permalink to “resolver”">​</a></h5><p><a href="./../#biomeresolver"><code>BiomeResolver</code></a></p><h5 id="zoomseed" tabindex="-1">zoomSeed <a class="header-anchor" href="#zoomseed" aria-label="Permalink to “zoomSeed”">​</a></h5><p><code>bigint</code></p><p>The jitter seed, which Java derives from the world seed with <a href="#obfuscateseed">obfuscateSeed</a>.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>BiomeManager</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="zoomseed-1" tabindex="-1">zoomSeed <a class="header-anchor" href="#zoomseed-1" aria-label="Permalink to “zoomSeed”">​</a></h3><blockquote><p><code>readonly</code> <strong>zoomSeed</strong>: <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/85a899ab0449aff681fea72169c1083e4f9748f7/packages/worldgen/src/biome/BiomeManager.ts#L114" target="_blank" rel="noreferrer">biome/BiomeManager.ts:114</a></p><p>The jitter seed, which Java derives from the world seed with <a href="#obfuscateseed">obfuscateSeed</a>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getbiome" tabindex="-1">getBiome() <a class="header-anchor" href="#getbiome" aria-label="Permalink to “getBiome()”">​</a></h3><blockquote><p><strong>getBiome</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/85a899ab0449aff681fea72169c1083e4f9748f7/packages/worldgen/src/biome/BiomeManager.ts#L139" target="_blank" rel="noreferrer">biome/BiomeManager.ts:139</a></p><p>Returns the biome identifier at one block position.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="withresolver" tabindex="-1">withResolver() <a class="header-anchor" href="#withresolver" aria-label="Permalink to “withResolver()”">​</a></h3><blockquote><p><strong>withResolver</strong>(<code>resolver</code>): <code>BiomeManager</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/85a899ab0449aff681fea72169c1083e4f9748f7/packages/worldgen/src/biome/BiomeManager.ts#L134" target="_blank" rel="noreferrer">biome/BiomeManager.ts:134</a></p><p>Returns a source with the same jitter seed but a different biome layout.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="resolver-1" tabindex="-1">resolver <a class="header-anchor" href="#resolver-1" aria-label="Permalink to “resolver”">​</a></h5><p><a href="./../#biomeresolver"><code>BiomeResolver</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>BiomeManager</code></p><hr><h3 id="obfuscateseed" tabindex="-1">obfuscateSeed() <a class="header-anchor" href="#obfuscateseed" aria-label="Permalink to “obfuscateSeed()”">​</a></h3><blockquote><p><code>static</code> <strong>obfuscateSeed</strong>(<code>seed</code>): <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/85a899ab0449aff681fea72169c1083e4f9748f7/packages/worldgen/src/biome/BiomeManager.ts#L127" target="_blank" rel="noreferrer">biome/BiomeManager.ts:127</a></p><p>Derives the jitter seed from a world seed.</p><p>Java hashes the seed with SHA-256 and reads the first eight bytes of the digest as a little-endian <code>long</code>, which is Guava&#39;s <code>Hashing.sha256().hashLong(seed).asLong()</code>.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="seed" tabindex="-1">seed <a class="header-anchor" href="#seed" aria-label="Permalink to “seed”">​</a></h5><p><code>bigint</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>bigint</code></p>`,57)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};